class OrderAdapter(
    private val ctx: JMSContext,
    private val queue: Queue,
    private val handler: (Order) -> Unit,
) {
    fun start() = ctx.createConsumer(queue).setMessageListener { m ->
        handler(parse((m as TextMessage).text))     // SAM conversion -> lambda
    }

    fun publish(o: Order) = ctx.createProducer().send(queue, encode(o))
}
